package studio.solocamera;
public final class SpeechCleanupTest {
    static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
    public static void main(String[] args){SpeechCleanup engine=new SpeechCleanup(48000,2);double noiseIn=0,noiseOut=0;for(int i=0;i<96000;i++){float x=(float)(.002*Math.sin(2*Math.PI*2000*i/48000));float y=engine.sample(x,0,.9);if(i>48000){noiseIn+=x*x;noiseOut+=y*y;}check(engine.sample(0,1,.9)==0,"Channel leakage");}check(noiseOut<noiseIn*.4,"Quiet background not reduced");engine.reset();double voice=0;for(int i=0;i<48000;i++){float x=(float)(.12*Math.sin(2*Math.PI*600*i/48000));float y=engine.sample(x,0,.6);if(i>24000)voice+=y*y;check(Float.isFinite(y)&&Math.abs(y)<=.98,"Unbounded output");}check(Math.sqrt(voice/23999)>.06,"Voice over-attenuated");engine.reset();for(int i=0;i<48000;i++)engine.sample(.2f,0,.9);check(Math.abs(engine.sample(.2f,0,.9))<.03,"DC rumble not reduced");engine.reset();check(engine.sample(0,0,.6)==0,"Reset retained history");check(Float.isFinite(engine.sample(Float.NaN,0,.6)),"Nonfinite input propagated");System.out.println("PASS background attenuation, voice retention, stereo isolation, bounded output, DC rejection and reset");}
}
